import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    static class Effect {
        long a, b;

        Effect(long a, long b) {
            this.a = a;
            this.b = b;
        }
    }

    static class Line {
        long a, b, start;

        Line(long a, long b, long start) {
            this.a = a;
            this.b = b;
            this.start = start;
        }
    }

    static long ceilDiv(long numerator, long denominator) {
        return -Math.floorDiv(-numerator, denominator);
    }

    static long modPow(long base, long exp) {
        long result = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) != 0) result = result * base % MOD;
            base = base * base % MOD;
            exp >>= 1;
        }
        return result;
    }

    static int findLine(ArrayList<Line> hull, long y) {
        int lo = 0, hi = hull.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (hull.get(mid).start <= y) lo = mid + 1;
            else hi = mid;
        }
        return lo - 1;
    }

    static long applyRepeated(long value, Line line, long count) {
        long power = modPow(line.a, count);
        long geometric = (power - 1 + MOD) % MOD;
        geometric = geometric * modPow(line.a - 1, MOD - 2) % MOD;
        return (power * value + (line.b % MOD) * geometric) % MOD;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();
        long k = fs.nextLong();

        long[] spellA = new long[n];
        long[] spellB = new long[n];
        for (int i = 0; i < n; i++) spellA[i] = fs.nextLong();
        for (int i = 0; i < n; i++) spellB[i] = fs.nextLong();

        Effect[] meals = new Effect[m];
        for (int i = 0; i < m; i++) meals[i] = new Effect(fs.nextLong(), 0);
        for (int i = 0; i < m; i++) meals[i].b = fs.nextLong();

        Arrays.sort(meals, (u, v) -> {
            long du = u.a - 1;
            long dv = v.a - 1;
            if (du == 0 && dv != 0) return -1;
            if (dv == 0 && du != 0) return 1;
            if (du == 0) return 0;
            return Long.compare(v.b * du, u.b * dv);
        });

        long mealA = 1, mealB = 0;
        for (Effect meal : meals) {
            mealA = meal.a % MOD * mealA % MOD;
            mealB = (meal.a % MOD * mealB + meal.b) % MOD;
        }

        Effect[] spells = new Effect[n];
        for (int i = 0; i < n; i++) spells[i] = new Effect(spellA[i], spellB[i]);
        Arrays.sort(spells, (u, v) -> {
            int cmp = Long.compare(u.a, v.a);
            return cmp != 0 ? cmp : Long.compare(v.b, u.b);
        });

        ArrayList<Line> hull = new ArrayList<>();
        for (int i = 0; i < n; ) {
            long a = spells[i].a;
            long b = spells[i].b;
            while (i < n && spells[i].a == a) {
                b = Math.max(b, spells[i].b);
                i++;
            }

            if (hull.isEmpty()) {
                hull.add(new Line(a, b, Long.MIN_VALUE));
                continue;
            }

            long start;
            while (true) {
                Line last = hull.get(hull.size() - 1);
                start = ceilDiv(last.b - b, a - last.a);
                if (start <= last.start) {
                    hull.remove(hull.size() - 1);
                    if (hull.isEmpty()) break;
                } else {
                    break;
                }
            }
            if (hull.isEmpty()) hull.add(new Line(a, b, Long.MIN_VALUE));
            else hull.add(new Line(a, b, start));
        }

        int q = fs.nextInt();
        StringBuilder out = new StringBuilder();

        for (int qi = 0; qi < q; qi++) {
            long x = fs.nextLong();
            long y = x;
            long value = x % MOD;
            long remaining = k;

            while (remaining > 0) {
                int idx = findLine(hull, y);
                Line line = hull.get(idx);

                if (line.a == 1) {
                    if (idx == hull.size() - 1) {
                        value = (value + (remaining % MOD) * (line.b % MOD)) % MOD;
                        remaining = 0;
                    } else {
                        long threshold = hull.get(idx + 1).start;
                        long steps = (threshold - y + line.b - 1) / line.b;
                        long take = Math.min(remaining, steps);
                        y += take * line.b;
                        value = (value + (take % MOD) * (line.b % MOD)) % MOD;
                        remaining -= take;
                    }
                } else if (idx == hull.size() - 1) {
                    value = applyRepeated(value, line, remaining);
                    remaining = 0;
                } else {
                    y = line.a * y + line.b;
                    value = (line.a % MOD * value + line.b) % MOD;
                    remaining--;
                }
            }

            long answer = (mealA * value + mealB) % MOD;
            out.append(answer).append('\n');
        }

        System.out.print(out);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}
